func (this *Gemini) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// fetchTickers
	//
	//     {
	//         "pair": "BATUSD",
	//         "price": "0.20687",
	//         "percentChange24h": "0.0146"
	//     }
	//
	// fetchTickerV1
	//
	//     {
	//         "bid":"9117.95",
	//         "ask":"9117.96",
	//         "volume":{
	//             "BTC":"1615.46861748",
	//             "USD":"14727307.57545006088",
	//             "timestamp":1594982700000
	//         },
	//         "last":"9115.23"
	//     }
	//
	// fetchTickerV2
	//
	//     {
	//         "symbol":"BTCUSD",
	//         "open":"9080.58",
	//         "high":"9184.53",
	//         "low":"9063.56",
	//         "close":"9116.08",
	//         // Hourly prices descending for past 24 hours
	//         "changes":["9117.33","9105.69","9106.23","9120.35","9098.57","9114.53","9113.55","9128.01","9113.63","9133.49","9133.49","9137.75","9126.73","9103.91","9119.33","9123.04","9124.44","9117.57","9114.22","9102.33","9076.67","9074.72","9074.97","9092.05"],
	//         "bid":"9115.86",
	//         "ask":"9115.87"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var volume any = this.SafeValue(ticker, "volume", map[string]any{})
	var timestamp any = this.SafeInteger(volume, "timestamp")
	var symbol any = nil
	var marketId any = this.SafeStringLower(ticker, "pair")
	market = this.SafeMarket(marketId, market)
	var baseId any = nil
	var quoteId any = nil
	var base any = nil
	var quote any = nil
	if IsTrue(IsTrue((!IsEqual(marketId, nil))) && IsTrue((IsEqual(market, nil)))) {
		var idLength any = Subtract(GetLength(marketId), 0)
		if IsTrue(IsEqual(idLength, 7)) {
			baseId = Slice(marketId, 0, 4)
			quoteId = Slice(marketId, 4, 7)
		} else {
			baseId = Slice(marketId, 0, 3)
			quoteId = Slice(marketId, 3, 6)
		}
		base = this.SafeCurrencyCode(baseId)
		quote = this.SafeCurrencyCode(quoteId)
		symbol = Add(Add(base, "/"), quote)
	}
	if IsTrue(IsTrue((IsEqual(symbol, nil))) && IsTrue((!IsEqual(market, nil)))) {
		symbol = GetValue(market, "symbol")
		baseId = this.SafeStringUpper(market, "baseId")
		quoteId = this.SafeStringUpper(market, "quoteId")
	}
	var price any = this.SafeString(ticker, "price")
	var last any = this.SafeString2(ticker, "last", "close", price)
	var percentage any = this.SafeString(ticker, "percentChange24h")
	var open any = this.SafeString(ticker, "open")
	var baseVolume any = this.SafeString(volume, baseId)
	var quoteVolume any = this.SafeString(volume, quoteId)
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.SafeString(ticker, "high"),
		"low":           this.SafeString(ticker, "low"),
		"bid":           this.SafeString(ticker, "bid"),
		"bidVolume":     nil,
		"ask":           this.SafeString(ticker, "ask"),
		"askVolume":     nil,
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"info":          ticker,
	}, market)
}

